            n = 0
        customers = [i for i in range(n) if i != depot]
    else:
        customers = list(customers)

    def dem(i):
        if demands is None:
            return 1
        if 0 <= i < len(demands):
            d = demands[i]
            return 1 if d is None else d
        return 1

    def xy(i):
        if coords is None:
            return float(i), 0.0
        p = coords[i]
        return p[0], p[1]

    def dist(i, j):
        if i == j:
            return 0.0
        if coords is None:
            a = i - j
            return float(a * a) ** 0.5
        xi, yi = xy(i)
        xj, yj = xy(j)
        dx = xi - xj
        dy = yi - yj
        return (dx * dx + dy * dy) ** 0.5

    if capacity is None:
        capacity = sum(dem(c) for c in customers)
    if capacity <= 0:
        capacity = 1

    def load(route):
        s = 0
        for c in route:
            s += dem(c)
        return s

    def cost(route):
        if not route:
            return 0.0
        total = dist(depot, route[0]) + dist(route[-1], depot)
        for a, b in zip(route, route[1:]):
            total += dist(a, b)
        return total

    def two_opt(route):
        r = route[:]
        if len(r) < 4:
            return r
        improved = True
        while improved:
            improved = False
            n = len(r)
            for i in range(n - 1):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for k in range(i + 1, n):
                    c = r[k]
                    d = depot if k == n - 1 else r[k + 1]
                    if dist(a, c) + dist(b, d) + 1e-12 < dist(a, b) + dist(c, d):
                        r = r[:i] + r[i:k + 1][::-1] + r[k + 1:]
                        improved = True
                        break
                if improved:
                    break
        return r

    routes = [[c] for c in customers]
    pos = {c: i for i, c in enumerate(customers)}

    savings = []
    m = len(customers)
    for a in range(m):
        i = customers[a]
        di = dist(depot, i)
        for b in range(a + 1, m):
            j = customers[b]
            s = di + dist(depot, j) - dist(i, j)
            savings.append((s, i, j))
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    def route_index_of(node):
        return pos.get(node, None)

    for _, i, j in savings:
        ri = route_index_of(i)
        rj = route_index_of(j)
        if ri is None or rj is None or ri == rj:
            continue
        A = routes[ri]
        B = routes[rj]
        if not A or not B:
            continue
        if load(A) + load(B) > capacity:
            continue
        merged = None
        if A[-1] == i and B[0] == j:
            merged = A + B
        elif A[0] == i and B[-1] == j:
            merged = B + A
        elif A[0] == i and B[0] == j:
            merged = A[::-1] + B
        elif A[-1] == i and B[-1] == j:
            merged = A + B[::-1]
        if merged is None:
            continue
        routes[ri] = merged
        routes[rj] = []
        for c in merged:
            pos[c] = ri

    routes = [two_opt(r) for r in routes if r]

    def best_insert(route, c):
        if not route:
            return 0
        best_p = 0
        best_d = dist(depot, c) + dist(c, route[0]) - dist(depot, route[0])
        for p in range(1, len(route)):
            d = dist(route[p - 1], c) + dist(c, route[p]) - dist(route[p - 1], route[p])
            if d < best_d:
                best_d = d
                best_p = p
        d = dist(route[-1], c) + dist(c, depot) - dist(route[-1], depot)
        if d < best_d:
            best_p = len(route)
        return best_p

    changed = True
    while changed:
        changed = False
        i = 0
        while i < len(routes) and not changed:
            j = 0
            while j < len(routes):
                if i != j:
                    A = routes[i]
                    B = routes[j]
                    la = load(A)
                    lb = load(B)
                    base = cost(A) + cost(B)
                    for ia, a in enumerate(A):
                        da = dem(a)
                        if lb + da > capacity:
                            continue
                        A2 = A[:ia] + A[ia + 1:]
                        p = best_insert(B, a)
                        B2 = B[:p] + [a] + B[p:]
                        if cost(A2) + cost(B2) + 1e-12 < base:
                            routes[i] = two_opt(A2)
                            routes[j] = two_opt(B2)
                            changed = True
                            break
                    if changed:
                        break
                j += 1
            i += 1

    seen = set()
    final = []
    for r in routes:
        rr = []
        for c in r:
            if c not in seen:
                rr.append(c)
                seen.add(c)
        if rr:
            final.append(rr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        best_idx = None
        best_p = None
        best_d = None
        for idx, r in enumerate(final):
            if load(r) + dem(c) > capacity:
                continue
            p = best_insert(r, c)
            nr = r[:p] + [c] + r[p:]
            d = cost(nr) - cost(r)
            if best_d is None or d < best_d:
                best_d = d
                best_idx = idx
                best_p = p
        if best_idx is None:
            final.append([c])
        else:
            r = final[best_idx]
            final[best_idx] = r[:best_p] + [c] + r[best_p:]

    return final
